/**
 * RyanStevens.dev — Personal site / Curiosity Engine
 * Refactor version 2.0.0
 *
 * A personal website disguised as a Magic 8 Ball.
 * Vanilla JavaScript, CSS, Three.js and Cloudflare Workers.
 * No frontend framework. No database. Self-contained deployment.
 *
 * APPLICATION: request routing, page template, styles, browser logic, renderer.
 * CUSTOMIZATION: search for "EDITABLE CONFIGURATION" near the bottom.
 * IMAGES: the last section contains the four original Base64 photographs.
 *
 * All public content is public by design. Never put secrets in this file.
 * Made because I wanted to see if I could.
 */

// =============================================================================
// 01 — HTTP ROUTING
// =============================================================================

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const head = request.method === 'HEAD';
    if (request.method !== 'GET' && !head) {
      return new Response('Method not allowed', { status: 405, headers: { Allow: 'GET, HEAD' } });
    }
    const headers = {
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'strict-origin-when-cross-origin'
    };
    if (url.pathname === '/orb-engine.js') {
      return new Response(head ? null : ORB_ENGINE, { headers: {
        ...headers, 'Content-Type': 'application/javascript; charset=utf-8', 'Cache-Control': 'public, max-age=3600'
      } });
    }
    try {
      const data = getSiteData();
      const image = data.assets.get(url.pathname);
      if (image) {
        return new Response(head ? null : Uint8Array.from(atob(image.base64), c => c.charCodeAt(0)), {
          headers: { ...headers, 'Content-Type': image.mimeType, 'Cache-Control': 'public, max-age=3600' }
        });
      }
      if (url.pathname !== '/' && url.pathname !== '/index.html') {
        return new Response(head ? null : 'Not found', { status: 404 });
      }
      return new Response(head ? null : data.html, { headers: {
        ...headers, 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache'
      } });
    } catch (error) {
      console.error('RyanStevens.dev configuration error:', error.message);
      return new Response(head ? null : 'Site configuration error', { status: 500, headers });
    }
  }
};

// =============================================================================
// 02 — DATA PREPARATION AND VALIDATION
// =============================================================================

let cachedSite;
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, char => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[char]);
}
function scriptJson(value) {
  // HTML parsers recognize closing script tags even inside JS strings.
  return JSON.stringify(value, null, 2).replace(/[<>&\u2028\u2029]/g,
    char => '\\u' + char.charCodeAt(0).toString(16).padStart(4, '0'));
}
function requireValid(condition, message) {
  if (!condition) throw new Error(message);
}
function isPublicUrl(value) {
  try { return ['https:', 'http:', 'mailto:'].includes(new URL(value).protocol); }
  catch { return false; }
}
function imageVersion(base64) {
  // Non-cryptographic cache key: changes when the encoded image changes.
  let hash = 2166136261;
  for (let i = 0; i < base64.length; i++) {
    hash = Math.imul(hash ^ base64.charCodeAt(i), 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}
function getSiteData() {
  if (cachedSite) return cachedSite;
  const assets = new Map();
  const imageUrls = Object.create(null);
  for (const [id, image] of Object.entries(IMAGES)) {
    requireValid(/^\/pack\/[a-z0-9_-]+\.[a-z0-9]+$/i.test(image.path), `Invalid image path: ${id}`);
    requireValid(!assets.has(image.path), `Duplicate image path: ${image.path}`);
    requireValid(['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif'].includes(image.mimeType), `Invalid image type: ${id}`);
    const base64 = image.base64.replace(/\s/g, '');
    requireValid(base64.length > 0 && base64.length % 4 === 0 && /^[A-Za-z0-9+/]+={0,2}$/.test(base64), `Invalid Base64: ${id}`);
    // Validate encoding without storing decoded copies of all images.
    atob(base64);
    assets.set(image.path, { ...image, base64 });
    imageUrls[id] = `${image.path}?v=${imageVersion(base64)}`;
  }
  const questions = QUESTIONS.filter(question => question.enabled);
  requireValid(questions.length > 0, 'Enable at least one question.');
  const ids = new Set();
  for (const question of QUESTIONS) {
    for (const field of ['id', 'topic', 'question', 'orbAnswer', 'answerTitle', 'answerBody']) {
      requireValid(typeof question[field] === 'string' && question[field].trim(), `Missing ${field}: ${question.id}`);
    }
    requireValid(!ids.has(question.id), `Duplicate question ID: ${question.id}`);
    ids.add(question.id);
    if (question.orbAnswer.length > 16) console.warn(`Long orb answer: ${question.id} — test triangle fit.`);
    const action = question.action;
    if (!action) continue;
    requireValid(typeof action.label === 'string' && action.label.trim(), `Missing action label: ${question.id}`);
    if (action.type === 'gallery') requireValid(Object.hasOwn(GALLERIES, action.target), `Unknown gallery: ${action.target}`);
    else if (action.type === 'profile') requireValid(Object.hasOwn(PROFILES, action.target), `Unknown profile: ${action.target}`);
    else if (action.type === 'link') requireValid(isPublicUrl(action.url), `Invalid action URL: ${question.id}`);
    else throw new Error(`Unknown action type: ${action.type}`);
  }
  for (const [id, gallery] of Object.entries(GALLERIES)) {
    requireValid(Array.isArray(gallery.photos) && gallery.photos.length > 0, `Empty gallery: ${id}`);
    for (const photo of gallery.photos) requireValid(Object.hasOwn(imageUrls, photo.image), `Missing gallery image: ${photo.image}`);
  }
  for (const profile of Object.values(PROFILES)) requireValid(Object.hasOwn(imageUrls, profile.image), `Missing profile image: ${profile.image}`);
  requireValid(Object.hasOwn(PROFILES, 'robopup') && Object.hasOwn(GALLERIES, 'proton-pack'), 'Keep the default dialog entries (they may be edited).');
  for (const link of SITE.links) requireValid(isPublicUrl(link.url), `Invalid site link: ${link.label}`);
  requireValid(isPublicUrl(SITE.socialUrl), 'Invalid social URL.');
  requireValid(/^data:image\/svg\+xml,/.test(SITE.favicon) || /^https?:\/\//.test(SITE.favicon), 'Use an SVG data URL or HTTPS favicon URL.');
  for (const key of ['background','panel','line','text','mutedText','purple','cyan']) {
    requireValid(/^#(?:[0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(THEME[key]), `Invalid theme color: ${key}`);
  }
  requireValid(/^[a-z0-9 ,"'_-]+$/i.test(THEME.sansFont), 'Invalid font stack.');
  for (const key of ['maximumPageWidth','panelCornerRadius','mobilePanelCornerRadius','desktopBreakpoint']) {
    requireValid(Number.isInteger(THEME[key]) && THEME[key] > 0, `Invalid theme size: ${key}`);
  }
  for (const [key, value] of Object.entries(TIMING)) requireValid(Number.isFinite(value) && value >= 0, `Invalid timing: ${key}`);
  requireValid(Number.isInteger(TIMING.motionSampleCount) && TIMING.motionSampleCount > 0, 'motionSampleCount must be a positive integer.');
  requireValid(/^#[0-9a-f]{6}$/i.test(ORB_SETTINGS.shellColor), 'Orb shellColor must be a six-digit hex color.');
  for (const [key, value] of Object.entries(ORB_SETTINGS)) {
    if (key !== 'shellColor') requireValid(Number.isFinite(value) && value >= 0, `Invalid orb setting: ${key}`);
  }
  requireValid(ORB_SETTINGS.answerFontScale > 0, 'answerFontScale must be greater than zero.');
  const config = { questions, messages: MESSAGES, features: FEATURES, timing: TIMING,
    orbSettings: ORB_SETTINGS, galleries: GALLERIES, profiles: PROFILES, imageUrls };
  cachedSite = { assets, html: renderPage(config) };
  return cachedSite;
}

// =============================================================================
// 03 — HTML PAGE TEMPLATE
// =============================================================================

function renderPage(config) {
  const first = config.questions[0];
  const profile = PROFILES.robopup;
  const gallery = GALLERIES['proton-pack'];
  const historyMarkup = SITE.history.map(item => `<div><strong>${escapeHtml(item.company)}</strong><span>${escapeHtml(item.details)}</span></div>`).join('');
  const linksMarkup = SITE.links.map(link => `<a href="${escapeHtml(link.url)}">${escapeHtml(link.label)}</a>`).join('');
  const galleryMarkup = gallery.photos.map((photo, i) => `<button data-frame="${i}" aria-pressed="${i === 0}"><img src="${escapeHtml(config.imageUrls[photo.image])}" alt="" loading="lazy">${String(i + 1).padStart(2, '0')} / ${escapeHtml(photo.label)}</button>`).join('');
  return `<!doctype html>
<html lang="${escapeHtml(SITE.language)}">
<!--
  Oh, you're looking under the hood.

  I do that too.

  — Ryan
-->
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="${escapeHtml(THEME.background)}">
<meta name="description" content="${escapeHtml(SITE.description)}">
<meta property="og:title" content="${escapeHtml(SITE.socialTitle)}">
<meta property="og:description" content="${escapeHtml(SITE.socialDescription)}">
<meta property="og:type" content="website">
<meta property="og:url" content="${escapeHtml(SITE.socialUrl)}">
<title>${escapeHtml(SITE.pageTitle)}</title>
<link rel="icon" href="${escapeHtml(SITE.favicon)}">
<style>
${renderStyles()}
</style>
</head>
<body>
<header>
  <a class="brand" href="./" aria-label="${escapeHtml(SITE.homeLabel)}"><b>${escapeHtml(SITE.brandMark)}</b>${escapeHtml(SITE.brandName)}<span>${escapeHtml(SITE.brandSuffix)}</span></a><span class="eyebrow location">${escapeHtml(SITE.location)}</span>
</header>
<main>
<section class="intro" aria-labelledby="intro-title">
<div class="eyebrow">${escapeHtml(SITE.introEyebrow)}</div>
<h1 id="intro-title">${escapeHtml(SITE.headline)} <em>${escapeHtml(SITE.headlineAccent)}</em></h1>
<p class="lead">${escapeHtml(SITE.biography)}</p>
<p class="compact-lead"><strong>${escapeHtml(SITE.mobileRole)}</strong> ${escapeHtml(SITE.mobileBiography)}</p>
<div class="history" aria-label="${escapeHtml(SITE.historyLabel)}">${historyMarkup}</div>
<div class="links">${linksMarkup}</div>
</section>

<section class="oracle" aria-label="${escapeHtml(MESSAGES.oracleLabel)}">
<div class="oracle-top"><span class="eyebrow">${escapeHtml(MESSAGES.oracleHeading)}</span><span class="count" id="count">00 / ${config.questions.length}</span></div>
<h2 class="question" id="question">${escapeHtml(first.question)}</h2>
<div class="scene"><div class="orbit" aria-hidden="true"></div><button class="ball" id="ball" aria-label="${escapeHtml(MESSAGES.ballLabel)}" aria-describedby="hint"><span class="window" aria-hidden="true"><span class="eight">8</span><span class="answer"><span class="triangle"></span><span id="answer"></span></span></span></button></div>
<p class="hint" id="hint">${escapeHtml(MESSAGES.initialHint)}</p>
<div class="fact" id="fact" aria-live="polite" aria-atomic="true"><strong id="factTitle">${escapeHtml(MESSAGES.initialTitle)}</strong><p id="factBody">${escapeHtml(MESSAGES.initialBody)}</p></div>
<div class="next"><span class="eyebrow" id="nextLabel">${escapeHtml(MESSAGES.startQuestion)}</span><button id="nextQuestion">${escapeHtml(MESSAGES.questionOpen + first.question + MESSAGES.questionClose)}</button></div>
<div class="progress" id="progress" aria-hidden="true"></div>
<div class="tools"><button class="quiet" id="prev" hidden>${escapeHtml(MESSAGES.previous)}</button><button class="quiet" id="restart" hidden>${escapeHtml(MESSAGES.restart)}</button><button class="quiet" id="motion" hidden>${escapeHtml(MESSAGES.enableMotion)}</button></div>
<p id="motionStatus" class="sr" role="status"></p>
<noscript><p>${escapeHtml(MESSAGES.noScript)}</p></noscript>
</section>
<details class="index" id="index"><summary>${escapeHtml(MESSAGES.topicSummary)}</summary><nav id="topics" aria-label="${escapeHtml(MESSAGES.topicLabel)}"></nav></details>
</main>
<footer>
  <span>${escapeHtml(SITE.footerLeft)}</span><span>${escapeHtml(SITE.footerRight)}</span>
</footer>
<dialog id="roboDialog" aria-labelledby="roboTitle"><div class="eyebrow" id="roboKicker">${escapeHtml(profile.kicker)}</div><img class="robo-avatar" id="roboAvatar" src="${escapeHtml(config.imageUrls[profile.image])}" alt="${escapeHtml(profile.alt)}"><h2 id="roboTitle">${escapeHtml(profile.title)}</h2><p id="roboDescription">${escapeHtml(profile.description)}</p><button id="roboClose" autofocus>${escapeHtml(profile.closeLabel)}</button></dialog>
<dialog id="packDialog" aria-labelledby="packTitle"><div class="pack-stripe"></div><div class="pack-inner"><div class="pack-head"><div><div class="pack-kicker" id="packKicker">${escapeHtml(gallery.kicker)}</div><h2 id="packTitle">${escapeHtml(gallery.title)}</h2></div><button class="pack-close" id="packClose" autofocus>${escapeHtml(gallery.closeLabel)}</button></div><div class="pack-meta"><span>FILE: <b id="packFile">${escapeHtml(gallery.fileNumber)}</b></span><span>PROJECT: <b id="packProject">${escapeHtml(gallery.project)}</b></span><span>CLASS: <b id="packClass">${escapeHtml(gallery.classification)}</b></span></div><div class="pack-stage"><img id="packPhoto" alt=""></div><div class="pack-caption" aria-live="polite"><span id="packFrame">01 / ${String(gallery.photos.length).padStart(2, "0")}</span><span id="packCaption"></span></div><div class="pack-nav" id="packNav" aria-label="${escapeHtml(gallery.navigationLabel)}">${galleryMarkup}</div><div class="pack-bottom"><span id="packDisclaimer">${escapeHtml(gallery.disclaimer)}</span><b id="packWarning">${escapeHtml(gallery.warning)}</b></div></div><div class="pack-stripe"></div></dialog>
<script>
${startCuriosity.toString()}

// Public configuration: only content needed by the browser, never Base64 image data.
startCuriosity(${scriptJson(config)});
</script>
${FEATURES.enableWebGL ? '<script src="/orb-engine.js?v=rs-1" defer></script>' : ''}
</body>
</html>
`;
}

// =============================================================================
// 04 — CSS (original cascade retained; configurable theme values)
// =============================================================================

function renderStyles() {
  return `
:root {
  color-scheme: dark;
  --bg: ${THEME.background};
  --panel: ${THEME.panel};
  --line: ${THEME.line};
  --text: ${THEME.text};
  --muted: ${THEME.mutedText};
  --purple: ${THEME.purple};
  --cyan: ${THEME.cyan};
  --sans: ${THEME.sansFont};
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.65 var(--sans);
  min-height: 100svh;
}
button,a {
  -webkit-tap-highlight-color: transparent;
}
button {
  font: inherit;
  color: inherit;
  cursor: pointer;
}
a {
  color: inherit;
  text-decoration: none;
}
a:hover {
  color: var(--cyan);
}
button:focus-visible,a:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 5px;
}
button:disabled {
  cursor: wait;
}
header,main,footer {
  width: min(${THEME.maximumPageWidth}px,calc(100% - 64px));
  margin: auto;
}
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0 20px;
  border-bottom: 1px solid var(--line);
  gap: 16px;
}
.brand {
  font-size: 19px;
  font-weight: 650;
  letter-spacing: -.8px;
}
.brand span {
  color: var(--purple);
}
.brand b {
  font-weight: 400;
  color: var(--purple);
  margin-right: 9px;
}
.eyebrow {
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 1.8px;
  text-transform: uppercase;
  color: var(--muted);
}
.location {
  display: flex;
  align-items: center;
  gap: 8px;
}
.location:before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--cyan);
}
main {
  display: grid;
  grid-template-columns: minmax(0,.86fr) minmax(0,1.14fr);
  gap: clamp(24px,5vw,72px);
  align-items: center;
  padding: 34px 0 28px;
}
.intro {
  padding: 12px 0;
}
.intro h1 {
  font-size: clamp(42px,5.3vw,72px);
  font-weight: 550;
  letter-spacing: -.065em;
  line-height: 1.04;
  margin: 22px 0 23px;
}
.intro h1 em {
  font: italic 400 1em/1.04 Georgia,serif;
  letter-spacing: -.055em;
  color: var(--purple);
  display: block;
}
.lead {
  font-size: 16px;
  color: var(--muted);
  max-width: 39ch;
  margin: 0 0 24px;
}
.lead strong {
  color: var(--text);
  font-weight: 600;
}
.history {
  margin: 28px 0 24px;
  border-top: 1px solid var(--line);
}
.history div {
  padding: 13px 0;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 15px;
  align-items: baseline;
  justify-content: space-between;
}
.history strong {
  font-size: 14px;
  font-weight: 600;
}
.history span {
  color: var(--muted);
  font-size: 12px;
  text-align: right;
}
.links {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 20px;
  align-items: center;
  font-size: 13px;
}
.links a {
  color: var(--purple);
}
.links a:hover {
  color: var(--cyan);
}
.labnote {
  color: var(--muted);
  font-size: 12px;
  margin-top: 25px;
}
.oracle {
  position: relative;
  isolation: isolate;
  text-align: center;
  border: 1px solid #b9b3d226;
  border-radius: ${THEME.panelCornerRadius}px;
  background: radial-gradient(ellipse at 50% 44%,#353044 0%,#242434 30%,transparent 67%),var(--panel);
  padding: 22px 28px 18px;
  overflow: hidden;
}
.oracle-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.count {
  font: 11px ui-monospace,monospace;
  color: var(--purple);
  font-variant-numeric: tabular-nums;
}
.question {
  font-size: clamp(23px,3vw,35px);
  font-weight: 540;
  letter-spacing: -.045em;
  line-height: 1.13;
  margin: 17px auto 0;
  min-height: 2.26em;
  max-width: 24ch;
  display: grid;
  place-items: center;
}
.scene {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 270px;
  height: clamp(270px,34vh,340px);
  isolation: isolate;
}
.scene:before {
  content: "";
  position: absolute;
  inset: 15% 4%;
  background: radial-gradient(ellipse,#7464a02d,transparent 65%);
  pointer-events: none;
}
.orbit {
  position: absolute;
  border: 1px solid #c6b6fa17;
  border-radius: 50%;
  width: 88%;
  height: 29%;
  transform: rotate(-18deg);
  z-index: -1;
}
.orbit:after {
  content: "✦";
  position: absolute;
  right: 9%;
  top: 6%;
  color: var(--purple);
  font-size: 12px;
}
.ball {
  --dx: 0px;
  --dy: 0px;
  --rot: 0deg;
  position: relative;
  display: grid;
  place-items: center;
  width: min(79%,280px);
  aspect-ratio: 1;
  border-radius: 50%;
  border: 1px solid #5d5b682e;
  isolation: isolate;
  touch-action: none;
  user-select: none;
  background: radial-gradient(ellipse at 30% 15%,#45444e 0%,#262733 12%,#11121a 34%,#08090d 63%,#030305 88%);
  box-shadow: inset -14px -16px 26px #000,inset 1px 1px 3px #d3d5ed25,12px 27px 45px #0009;
  transform: translate(var(--dx),var(--dy)) rotate(var(--rot));
  transition: transform .25s ease;
  cursor: grab;
}
.ball:active {
  cursor: grabbing;
}
.ball:before {
  content: "";
  position: absolute;
  left: 12%;
  top: 9%;
  width: 39%;
  height: 12%;
  border-radius: 50%;
  background: #ffffff20;
  filter: blur(9px);
  transform: rotate(-25deg);
  pointer-events: none;
}
.ball:after {
  content: "";
  position: absolute;
  inset: 3%;
  border-radius: 50%;
  border-top: 1px solid #f4eaff28;
  border-right: 1px solid #b3d4ff15;
  pointer-events: none;
}
.window {
  position: relative;
  width: 64%;
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 7px solid #11131a;
  box-shadow: 0 0 0 2px #75798965,0 0 0 5px #07080c,inset 0 5px 20px #0009,inset 0 -12px 24px #0c2b4655;
  background: radial-gradient(circle at 35% 25%,#78949e,#385664 53%,#1a2935 82%);
}
.window:after {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(ellipse at 20% 22%,#ffffff25,transparent 35%),repeating-radial-gradient(ellipse at 55% 58%,transparent 0 14px,#8bc9ff0b 16px 17px,transparent 20px 29px);
  box-shadow: inset 0 0 12px #b2b6ff17;
}
.eight {
  display: grid;
  place-items: center;
  width: 76%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: #e2e2df;
  color: #23252b;
  font: 800 clamp(55px,8vw,85px)/1 Arial,sans-serif;
  box-shadow: inset 0 -8px 16px #7b8188;
  transition: opacity .25s;
}
.answer {
  position: absolute;
  inset: 5%;
  display: grid;
  place-items: center;
  opacity: 0;
  filter: blur(10px);
  transition: opacity .45s,filter .7s;
}
.triangle {
  position: absolute;
  inset: 0;
  clip-path: polygon(50% 0,98% 89%,2% 89%);
  background: linear-gradient(155deg,#9bb4d0,#526d9c 70%,#4a517c);
}
.answer span {
  z-index: 1;
  margin-top: 14%;
  max-width: 75%;
  font-size: clamp(9px,1.4vw,13px);
  font-weight: 750;
  letter-spacing: 1px;
  color: white;
  line-height: 1.2;
  text-transform: uppercase;
}
.ball.revealed .eight,.ball.shaking .eight {
  opacity: 0;
}
.ball.revealed .answer {
  opacity: 1;
  filter: none;
}
.ball.shaking .answer {
  opacity: .3;
  filter: blur(12px);
}
.ball.shaking {
  animation: shake .55s ease both;
}
.ball.dragging {
  transition: none;
}
@keyframes shake {
  0%,100% {
    transform: translate(0) rotate(0);
  }
  20% {
    transform: translate(-14px,7px) rotate(-12deg);
  }
  40% {
    transform: translate(13px,-6px) rotate(13deg);
  }
  60% {
    transform: translate(-10px,5px) rotate(-8deg);
  }
  80% {
    transform: translate(6px,-3px) rotate(5deg);
  }
}
.hint {
  font-size: 10px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: var(--purple);
  margin: 1px 0 14px;
}
.fact {
  min-height: 96px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  margin: 0 auto 13px;
  max-width: 47ch;
}
.fact strong {
  font-size: 17px;
  line-height: 1.3;
  font-weight: 600;
}
.fact p {
  font-size: 13px;
  line-height: 1.55;
  color: var(--muted);
  margin: 0;
}
.next {
  border-top: 1px solid var(--line);
  padding-top: 14px;
  display: grid;
  gap: 5px;
  justify-items: center;
}
.next button {
  border: 0;
  background: none;
  padding: 7px 8px 4px;
  font: italic 19px/1.3 Georgia,serif;
  color: var(--text);
}
.next button:hover {
  color: var(--cyan);
}
.next .eyebrow {
  font-size: 9px;
}
.progress {
  display: flex;
  justify-content: center;
  gap: 5px;
  margin: 12px 0 0;
}
.progress span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ffffff20;
}
.progress span.done {
  background: var(--purple);
}
.progress span.current {
  background: var(--cyan);
  box-shadow: 0 0 8px #68ddd94d;
}
.tools {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px 14px;
  margin-top: 12px;
}
.quiet {
  border: 0;
  background: none;
  color: var(--muted);
  font-size: 11px;
  padding: 5px 6px;
}
.quiet:hover {
  color: var(--cyan);
}
.quiet[hidden] {
  display: none;
}
.index {
  grid-column: 1/-1;
  border-top: 1px solid var(--line);
  padding: 16px 0 0;
}
.index summary {
  cursor: pointer;
  font-size: 13px;
  color: var(--muted);
}
.index nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 14px 0;
}
.index button {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 20px;
  font-size: 12px;
  padding: 7px 13px;
}
.index button:hover {
  border-color: var(--purple);
}
footer {
  border-top: 1px solid var(--line);
  padding: 15px 0 20px;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: var(--muted);
  font-size: 11px;
}
.sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
noscript p {
  color: var(--muted);
}
@media (max-width:${THEME.desktopBreakpoint}px) {
  header,main,footer {
    width: calc(100% - 36px);
  }
  header {
    padding: 18px 0;
  }
  .brand {
    font-size: 17px;
  }
  .location {
    font-size: 9px;
  }
  main {
    grid-template-columns: 1fr;
    gap: 24px;
    padding-top: 18px;
  }
  .intro {
    padding: 8px 0 0;
  }
  .intro h1 {
    font-size: clamp(40px,9vw,62px);
    margin: 14px 0;
  }
  .lead {
    margin-bottom: 16px;
  }
  .history {
    margin: 18px 0;
  }
  .labnote {
    display: none;
  }
  .oracle {
    padding: 18px 18px 16px;
  }
  .scene {
    height: 280px;
  }
  .ball {
    width: min(76%,255px);
  }
  .question {
    min-height: 2.26em;
  }
  .fact {
    min-height: 104px;
  }
  .index {
    grid-column: auto;
  }
  footer {
    flex-wrap: wrap;
  }
}
@media (max-width:360px) {
  .location {
    display: none;
  }
  .history div {
    gap: 8px;
  }
  .oracle {
    padding: 15px 12px;
  }
  .scene {
    height: 250px;
    min-height: 250px;
  }
  .ball {
    width: 76%;
  }
}
@media (prefers-reduced-motion:reduce) {
  *,*:before,*:after {
    animation: none !important;
    transition: none !important;
  }
}
.ball {
  width: 252px;
  height: 252px;
  border-radius: 50%;
  border: 0;
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  isolation: isolate;
  background: radial-gradient(
          ellipse at 32% 16%,
          #393e3a 0%,
          #1e2420 13%,
          #0f1411 34%,
          #090d0a 68%,
          #030403 88%
        );
  box-shadow: inset -14px -16px 26px #000,
          inset 1px 1px 3px #c1d4ae20,
          12px 27px 45px #0009;
  transform: none !important;
  animation: none !important;
  top: 0;
}
.ball:before {
  content: "";
  position: absolute;
  left: 40px;
  top: 20px;
  width: 100px;
  height: 30px;
  border-radius: 50%;
  background: rgb(255 255 255 / 0.13);
  filter: blur(13px);
}
.window {
  width: 136px;
  height: 136px;
  border-radius: 50%;
  border: 7px solid #111713;
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: radial-gradient(circle at 50% 38%, #697c89 0%, #34404a 42%, #161b20 78%),
          #03080d;
  box-shadow: 0 1px 1px #ffffff0d,
          inset 0 5px 18px #000,
          inset 0 -12px 24px #0c2b4655;
}
.window:before {
  content: "";
  position: absolute;
  inset: 4px;
  z-index: 4;
  pointer-events: none;
  border-radius: 50%;
  background: radial-gradient(ellipse at 32% 24%, #ffffff18 0 12%, transparent 28%),
          repeating-radial-gradient(
            ellipse at 55% 58%,
            transparent 0 14px,
            #8bc9ff0b 16px 17px,
            transparent 20px 29px
          );
  mix-blend-mode: screen;
  backdrop-filter: blur(1.25px) saturate(1.12);
  animation: liquidRipple 5.6s ease-in-out infinite alternate;
}
.window:after {
  content: "";
  position: absolute;
  inset: 8px;
  z-index: 3;
  pointer-events: none;
  border-radius: 50%;
  border: 1px solid #8dcaff18;
  box-shadow: inset 11px 5px 20px #8bc9ff0b,
          inset -9px -13px 22px #00111f99;
  transform: scaleX(0.985) rotate(-3deg);
}
.window > * {
  z-index: 2;
}
.eight {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #e7ebd8;
  color: #101710;
  font: 800 70px Arial;
  box-shadow: inset 0 -8px 16px #7b8874;
  transition: opacity 0.3s;
}
.answer {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  filter: blur(14px);
  transition: opacity 1s,
          filter 1.6s;
}
.triangle {
  position: absolute;
  inset: 10px 6px 7px;
  clip-path: polygon(50% 0, 100% 88%, 0 88%);
  background: linear-gradient(160deg, #aabaff, #334fc2 70%);
}
.answer span {
  position: relative;
  color: white;
  font: 700 10px/1.4 "DM Sans",
          sans-serif;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  width: 73px;
  margin-top: 10px;
}
.revealed .eight,
      .thinking .eight {
  opacity: 0;
}
.revealed .answer {
  opacity: 1;
  filter: blur(0);
}
.thinking .answer {
  opacity: 0.5;
  filter: blur(14px);
}
.thinking .triangle {
  animation: swirl 1.8s ease-in-out;
}
.ball.blink .window {
  animation: blink 0.45s ease-in-out;
}
.ball.floating {
  top: -12px;
  transition: top 1s;
}
.orb-webgl {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  cursor: default;
  z-index: 1;
}
.scene.webgl-ready #ball {
  background: transparent;
  box-shadow: none;
  border: 0;
  overflow: visible;
}
.scene.webgl-ready #ball:before,
      .scene.webgl-ready #ball:after {
  display: none;
}
.scene.webgl-ready #ball > .window {
  visibility: hidden;
}
.scene.webgl-ready .orbit {
  opacity: 0.22;
}
.scene #ball:focus-visible {
  outline: 2px solid var(--lime);
  outline-offset: 4px;
  border-radius: 50%;
}
/* Adapt the original fallback to this page; the 3D engine owns the rendered sphere. */
:root {
  --lime: var(--purple);
}
.scene #ball {
  width: min(79%,280px);
  height: auto;
  aspect-ratio: 1;
  z-index: 2;
  padding: 0;
  touch-action: none;
  cursor: pointer;
}
.scene #ball .window {
  width: 54%;
  height: 54%;
  aspect-ratio: 1;
}
.scene #ball .eight {
  width: 72%;
  height: 72%;
  aspect-ratio: 1;
  font-size: clamp(42px,6vh,70px);
}
.scene #ball .answer {
  inset: 0;
}
.scene #ball .answer span {
  position: relative;
  z-index: 2;
  text-align: center;
  font-size: clamp(18px,1.8vh,24px);
  width: 65%;
  max-width: 65%;
  margin: 10px 0 0;
  letter-spacing: .5px;
  line-height: 1.2;
}
.scene #ball .triangle {
  inset: 10px 6px 7px;
  clip-path: polygon(50% 0,100% 88%,0 88%);
}
.scene:not(.webgl-ready) #ball {
  transform: translate(var(--dx,0px),var(--dy,0px)) rotate(var(--rot,0deg)) !important;
}
.scene:not(.webgl-ready) #ball.shaking {
  animation: shake .55s ease both !important;
}
.scene.webgl-ready #ball {
  transform: none !important;
  animation: none !important;
  transition: none !important;
}
.scene.webgl-ready #ball .window {
  visibility: hidden;
}
@media (prefers-reduced-motion:reduce) {
  .scene:not(.webgl-ready) #ball.shaking {
    animation: none !important;
  }
}
/* Single-screen layout: the orb scene absorbs available space. */
html {
  height: 100%;
}
body {
  height: 100dvh;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
header {
  flex: none;
  padding: clamp(10px,2vh,24px) 0;
  border-bottom: 1px solid var(--line);
}
main {
  flex: 1;
  min-height: 0;
  grid-template-rows: minmax(0,1fr) auto;
  align-items: stretch;
  gap: 12px clamp(24px,5vw,72px);
  padding: clamp(10px,2vh,26px) 0 8px;
}
.intro {
  align-self: center;
  min-height: 0;
  padding: 0;
}
.intro h1 {
  font-size: clamp(36px,min(5.3vw,8.5vh),72px);
  margin: clamp(10px,2vh,22px) 0;
}
.lead {
  margin-bottom: 12px;
}
.history {
  margin: clamp(12px,2.4vh,26px) 0;
}
.history div {
  padding: clamp(6px,1.3vh,13px) 0;
}
.labnote {
  margin-top: clamp(8px,2vh,25px);
}
.oracle {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: clamp(12px,2vh,22px) clamp(14px,2.2vw,28px) 10px;
}
.oracle-top,.question,.hint,.fact,.next,.progress,.tools {
  flex: none;
}
.question {
  font-size: clamp(22px,min(3vw,4.2vh),35px);
  min-height: 2.26em;
  margin: 8px auto 0;
}
.scene {
  height: auto;
  min-height: 90px;
  flex: 1;
  min-width: 0;
}
.hint {
  margin: 2px 0 7px;
}
.fact {
  min-height: 78px;
  margin: 0 auto 8px;
  gap: 4px;
}
.fact strong {
  font-size: 16px;
}
.fact p {
  font-size: 13px;
  line-height: 1.45;
}
.next {
  padding-top: 8px;
  gap: 2px;
}
.next button {
  font-size: 17px;
  padding: 4px 8px 2px;
}
.progress {
  margin: 8px 0 0;
}
.tools {
  margin-top: 5px;
  min-height: 26px;
  gap: 5px 10px;
}
.quiet {
  padding: 3px 6px;
}
.index {
  position: relative;
  padding: 7px 0 0;
  z-index: 4;
}
.index nav {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  background: var(--panel);
  border: 1px solid #b9b3d245;
  border-radius: 14px;
  padding: 12px;
  margin: 0 0 7px;
  box-shadow: 0 12px 32px #0009;
  max-height: min(40dvh,240px);
  overflow: auto;
}
footer {
  flex: none;
  padding: 8px 0 10px;
}
.compact-lead {
  display: none;
}
@media (max-height:740px) and (min-width:${THEME.desktopBreakpoint + 1}px) {
  .labnote {
    display: none;
  }
  .fact {
    min-height: 70px;
  }
  .question {
    font-size: clamp(21px,3.8vh,29px);
  }
  .oracle {
    padding-top: 10px;
  }
  .lead {
    font-size: 14px;
  }
  .history div {
    font-size: 12px;
  }
}
@media (max-width:${THEME.desktopBreakpoint}px) {
  header,main,footer {
    width: calc(100% - 28px);
  }
  header {
    padding: 9px 0;
    gap: 8px;
  }
  main {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0,1fr) auto;
    gap: 8px;
    padding: 8px 0 5px;
  }
  .intro {
    align-self: start;
  }
  .intro h1 {
    font-size: clamp(25px,6.2vw,42px);
    margin: 3px 0 5px;
    line-height: 1.12;
    letter-spacing: -.05em;
  }
  .intro h1 em {
    display: inline;
    letter-spacing: -.04em;
  }
  .intro>.eyebrow {
    font-size: 9px;
  }
  .lead {
    display: none;
  }
  .compact-lead {
    display: block;
    color: var(--muted);
    font-size: 12px;
    line-height: 1.35;
    margin: 0 0 5px;
  }
  .compact-lead strong {
    color: var(--text);
    font-weight: 600;
  }
  .history {
    display: none;
  }
  .links {
    font-size: 11px;
    gap: 5px 15px;
  }
  .oracle {
    padding: 10px 12px 6px;
    border-radius: ${THEME.mobilePanelCornerRadius}px;
  }
  .oracle-top .eyebrow {
    font-size: 9px;
    letter-spacing: 1px;
  }
  .question {
    font-size: clamp(19px,5.2vw,27px);
    margin: 5px auto 0;
    min-height: 2.15em;
    max-width: 27ch;
  }
  .scene {
    min-height: 85px;
    height: auto;
  }
  .hint {
    font-size: 9px;
    margin: 0 0 5px;
    letter-spacing: .9px;
  }
  .fact {
    min-height: 83px;
    max-width: 48ch;
    gap: 3px;
    margin-bottom: 5px;
  }
  .fact strong {
    font-size: 14px;
  }
  .fact p {
    font-size: 12px;
    line-height: 1.4;
  }
  .next {
    padding-top: 5px;
    gap: 0;
  }
  .next button {
    font-size: 15px;
    line-height: 1.2;
    padding: 3px 5px;
  }
  .next .eyebrow {
    font-size: 8px;
  }
  .progress {
    margin-top: 5px;
  }
  .tools {
    margin-top: 3px;
    min-height: 24px;
    gap: 3px 6px;
  }
  .quiet {
    font-size: 10px;
    padding: 3px 5px;
  }
  .index {
    grid-column: auto;
    padding-top: 3px;
  }
  .index summary {
    font-size: 11px;
  }
  footer {
    font-size: 9px;
    padding: 5px 0 6px;
    gap: 5px;
  }
}
@media (max-width:${THEME.desktopBreakpoint}px) and (max-height:700px) {
  .intro>.eyebrow {
    display: none;
  }
  .intro h1 {
    font-size: 25px;
  }
  .compact-lead {
    font-size: 11px;
  }
  .question {
    min-height: 1.2em;
    font-size: 20px;
  }
  .fact {
    min-height: 72px;
  }
  .fact p {
    font-size: 11px;
  }
  .fact strong {
    font-size: 13px;
  }
  .oracle {
    padding-top: 8px;
  }
  .next button {
    font-size: 14px;
  }
  .scene {
    min-height: 76px;
  }
}
@media (max-width:350px) and (max-height:640px) {
  header {
    padding: 5px 0;
  }
  main {
    gap: 5px;
    padding-top: 5px;
  }
  .intro h1 {
    font-size: 21px;
    margin: 0 0 3px;
  }
  .compact-lead {
    font-size: 10px;
    margin-bottom: 3px;
  }
  .links {
    font-size: 10px;
    gap: 4px 10px;
  }
  .oracle {
    padding: 7px 9px 4px;
  }
  .question {
    font-size: 18px;
    margin-top: 3px;
    min-height: 0;
  }
  .scene {
    min-height: 65px;
  }
  .fact {
    min-height: 0;
    gap: 2px;
    margin-bottom: 3px;
  }
  .fact p {
    font-size: 11px;
    line-height: 1.32;
  }
  .fact strong {
    font-size: 12px;
  }
  .hint {
    margin-bottom: 3px;
  }
  .next button {
    font-size: 13px;
  }
  .progress {
    margin-top: 3px;
  }
  .tools {
    margin-top: 1px;
    min-height: 20px;
  }
  .quiet {
    padding: 1px 4px;
  }
  footer {
    padding: 3px 0 4px;
    font-size: 8px;
  }
}
/* At extreme zoom or very short screens, keep text reachable instead of clipping. */
@media (max-height:520px) and (min-width:${THEME.desktopBreakpoint + 1}px),(max-height:560px) and (max-width:${THEME.desktopBreakpoint}px),(max-width:300px) {
  body {
    height: auto;
    min-height: 100dvh;
  }
  main {
    flex: none;
    grid-template-rows: auto auto;
  }
  .oracle {
    min-height: 420px;
  }
  .scene {
    min-height: 110px;
  }
  .intro {
    align-self: center;
  }
}
.pack-link {
  background: none;
  border: 0;
  color: var(--cyan);
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  padding: 0 3px;
  white-space: nowrap;
}
#packDialog {
  color: #eee8ce;
  background: #171b18;
  border: 1px solid #a49d72;
  border-radius: 5px;
  padding: 0;
  width: min(940px,calc(100vw - 28px));
  max-width: none;
  max-height: calc(100dvh - 28px);
  overflow: auto;
  box-shadow: 0 25px 100px #000b;
  font-family: ui-monospace,monospace;
  line-height: 1.4;
}
#packDialog::backdrop {
  background: #080a08e8;
  backdrop-filter: blur(7px);
}
#packDialog[open] {
  animation: packIn .23s ease-out;
}
@keyframes packIn {
  from {
    opacity: 0;
    transform: translateY(10px) scale(.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.pack-stripe {
  height: 10px;
  background: repeating-linear-gradient(135deg,#d9b744 0 15px,#252921 15px 30px);
}
.pack-inner {
  padding: clamp(12px,3vw,28px);
}
.pack-head {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 12px;
  border-bottom: 1px solid #77785c;
  padding-bottom: 12px;
}
.pack-kicker {
  font-size: 10px;
  letter-spacing: 2px;
  color: #d8bd62;
}
.pack-head h2 {
  font: 800 clamp(23px,4vw,38px)/1.05 system-ui;
  margin: 5px 0;
  color: #f4ecd3;
  letter-spacing: -1px;
}
.pack-close {
  background: #292d25;
  border: 1px solid #9c9977;
  color: #f4ecd3;
  padding: 8px 12px;
  font: 700 12px ui-monospace,monospace;
  white-space: nowrap;
}
.pack-close:hover,.pack-nav button:hover {
  background: #484b36;
}
.pack-meta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  color: #aeb69a;
  font-size: 11px;
  margin: 10px 0;
}
.pack-meta b {
  color: #d8bd62;
}
.pack-stage {
  height: clamp(160px,47dvh,490px);
  background: #0d100d;
  border: 1px solid #62684f;
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
}
.pack-stage img {
  width: 100%;
  height: 100%;
  min-height: 0;
  object-fit: contain;
}
.pack-stage:after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  box-shadow: inset 0 0 35px #0006;
}
.pack-caption {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin: 9px 0;
  color: #e9e3cb;
  font-size: 12px;
}
.pack-caption span:first-child {
  color: #d8bd62;
  white-space: nowrap;
}
.pack-nav {
  display: grid;
  grid-template-columns: repeat(var(--gallery-columns, 3),1fr);
  gap: 8px;
}
.pack-nav button {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #252b23;
  border: 1px solid #565d49;
  color: #b9c2a5;
  text-align: left;
  padding: 6px;
  font: 11px ui-monospace,monospace;
  min-width: 0;
}
.pack-nav button[aria-pressed=true] {
  border-color: #d8bd62;
  color: #f4ecd3;
  background: #383b28;
}
.pack-nav img {
  width: 54px;
  height: 38px;
  object-fit: cover;
}
.pack-bottom {
  color: #aeb69a;
  font-size: 10px;
  letter-spacing: .7px;
  margin-top: 12px;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.pack-bottom b {
  color: #cf6557;
}
@media (max-width:520px) {
  .pack-nav button {
    flex-direction: column;
    text-align: center;
    gap: 4px;
    font-size: 10px;
  }
  .pack-nav img {
    width: 100%;
    height: 42px;
  }
  .pack-stage {
    height: clamp(145px,42dvh,350px);
  }
  .pack-caption {
    font-size: 11px;
  }
  .pack-head h2 {
    font-size: 25px;
  }
  .pack-close {
    padding: 7px;
  }
  .pack-bottom {
    font-size: 9px;
  }
}
@media (prefers-reduced-motion:reduce) {
  #packDialog[open] {
    animation: none;
  }
}
.robo-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  vertical-align: middle;
  color: var(--cyan);
  border: 0;
  background: none;
  padding: 0 2px;
  font: inherit;
  cursor: pointer;
}
.robo-link img {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  object-fit: cover;
}
.robo-link:hover {
  text-decoration: underline;
}
#roboDialog {
  width: min(440px,calc(100% - 28px));
  max-height: calc(100dvh - 28px);
  overflow: auto;
  background: #101d30;
  color: #edf6ff;
  border: 1px solid #36617e;
  border-radius: 18px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 20px 80px #000b;
}
#roboDialog::backdrop {
  background: #080b13bc;
  backdrop-filter: blur(8px);
}
#roboDialog .robo-avatar {
  width: min(150px,28vh);
  aspect-ratio: 1;
  border-radius: 50%;
  object-fit: cover;
  display: block;
  margin: 12px auto;
  border: 2px solid #39cbff;
}
#roboDialog h2 {
  margin: 8px 0;
  font-size: 28px;
}
#roboDialog p {
  color: #b7ccdf;
  margin: 8px 0 18px;
}
#roboDialog button {
  background: #1d3550;
  border: 1px solid #4d7898;
  border-radius: 8px;
  padding: 8px 16px;
}
#roboDialog .eyebrow {
  color: #76d9ff;
}
`;
}

// =============================================================================
// 05 — BROWSER APPLICATION
// =============================================================================

/** Browser application. All editable data is passed in from the Worker. */
function startCuriosity(config) {
  'use strict';

  const { questions, messages, features, timing, orbSettings, galleries, profiles, imageUrls } = config;
  const $ = id => document.getElementById(id);
  const ball = $('ball');
  const question = $('question');
  const next = $('nextQuestion');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const facts = questions.slice();

  if (features.randomizeQuestions) {
    for (let i = facts.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [facts[i], facts[j]] = [facts[j], facts[i]];
    }
  }

  let cursor = -1;
  let busy = false;
  const revealed = new Set();
  let timer = 0;
  let drag = null;
  let skipClickUntil = 0;
  let motionEnabled = false;
  let motionLast = 0;
  let motionSamples = [];
  const pad = value => String(value).padStart(2, '0');
  const nextIndex = () => (cursor + 1) % facts.length;
  const nextText = fact => `${messages.questionOpen}${fact.question}${messages.questionClose}`;
  const wakeOrb = () => window.PSOrbWake?.();

  // Project dialogs: one profile template and one reusable gallery template.
  const robo = $('roboDialog');
  const pack = $('packDialog');
  let roboTrigger = null;
  let packTrigger = null;
  let packFrame = 0;
  let activeGallery = null;

  function openProfile(event, profileId) {
    const profile = profiles[profileId];
    if (!profile) return;
    roboTrigger = event.currentTarget;
    $('roboKicker').textContent = profile.kicker;
    $('roboTitle').textContent = profile.title;
    $('roboDescription').textContent = profile.description;
    $('roboAvatar').src = imageUrls[profile.image];
    $('roboAvatar').alt = profile.alt;
    $('roboClose').textContent = profile.closeLabel;
    robo.showModal();
    $('roboClose').focus();
  }

  $('roboClose').onclick = () => robo.close();
  robo.addEventListener('close', () => roboTrigger?.focus());

  function showPackFrame(index) {
    if (!activeGallery) return;
    const total = activeGallery.photos.length;
    packFrame = ((index % total) + total) % total;
    const frame = activeGallery.photos[packFrame];
    $('packPhoto').src = imageUrls[frame.image];
    $('packPhoto').alt = frame.alt;
    $('packFrame').textContent = `${pad(packFrame + 1)} / ${pad(total)}`;
    $('packCaption').textContent = frame.caption;
    pack.querySelectorAll('[data-frame]').forEach(button => {
      button.setAttribute('aria-pressed', String(Number(button.dataset.frame) === packFrame));
    });
  }

  function openGallery(event, galleryId) {
    const gallery = galleries[galleryId];
    if (!gallery) return;
    activeGallery = gallery;
    packTrigger = event.currentTarget;
    $('packKicker').textContent = gallery.kicker;
    $('packTitle').textContent = gallery.title;
    $('packClose').textContent = gallery.closeLabel;
    $('packFile').textContent = gallery.fileNumber;
    $('packProject').textContent = gallery.project;
    $('packClass').textContent = gallery.classification;
    $('packDisclaimer').textContent = gallery.disclaimer;
    $('packWarning').textContent = gallery.warning;
    $('packNav').setAttribute('aria-label', gallery.navigationLabel);
    $('packNav').style.setProperty('--gallery-columns', Math.min(3, gallery.photos.length));
    $('packNav').replaceChildren(...gallery.photos.map((frame, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.dataset.frame = String(index);
      const image = document.createElement('img');
      image.src = imageUrls[frame.image];
      image.alt = '';
      image.loading = 'lazy';
      button.append(image, `${pad(index + 1)} / ${frame.label}`);
      button.onclick = () => showPackFrame(index);
      return button;
    }));
    showPackFrame(0);
    pack.showModal();
    $('packClose').focus();
  }

  $('packClose').onclick = () => pack.close();
  pack.addEventListener('close', () => packTrigger?.focus());
  pack.addEventListener('keydown', event => {
    if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
      event.preventDefault();
      showPackFrame(packFrame + (event.key === 'ArrowRight' ? 1 : -1));
    }
  });
  pack.addEventListener('click', event => {
    if (event.target !== pack) return;
    const r = pack.getBoundingClientRect();
    if (event.clientX < r.left || event.clientX > r.right ||
        event.clientY < r.top || event.clientY > r.bottom) pack.close();
  });

  function appendAction(action) {
    if (!action) return;
    if (action.type === 'link') {
      const anchor = document.createElement('a');
      anchor.href = action.url;
      anchor.textContent = ' ' + action.label;
      anchor.style.color = 'var(--cyan)';
      $('factBody').append(anchor);
      return;
    }
    const button = document.createElement('button');
    button.type = 'button';
    if (action.type === 'profile') {
      const profile = profiles[action.target];
      button.className = 'robo-link';
      const image = document.createElement('img');
      image.src = imageUrls[profile.image];
      image.alt = '';
      button.append(image, action.label);
      button.onclick = event => openProfile(event, action.target);
    } else if (action.type === 'gallery') {
      button.className = 'pack-link';
      button.textContent = action.label;
      button.onclick = event => openGallery(event, action.target);
    } else return;
    $('factBody').append(' ', button);
  }

  // Question navigation and discovery progress.
  const dots = features.enableProgressDots ? facts.map(() => {
    const dot = document.createElement('span');
    $('progress').append(dot);
    return dot;
  }) : [];
  if (!features.enableProgressDots) $('progress').style.display = 'none';
  if (!features.enableTopicExplorer) $('index').hidden = true;
  if (features.enableTopicExplorer) facts.forEach((fact, index) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = fact.topic;
    button.onclick = () => {
      reveal(index);
      $('index').open = false;
    };
    $('topics').append(button);
  });

  function update() {
    const index = nextIndex();
    $('count').textContent = `${pad(revealed.size)} / ${facts.length}`;
    $('nextLabel').textContent = cursor < 0 ? messages.startQuestion :
      revealed.size === facts.length && index === 0 ? messages.allDiscovered : messages.nextQuestion;
    next.textContent = nextText(facts[index]);
    dots.forEach((dot, i) => {
      dot.classList.toggle('done', revealed.has(i));
      dot.classList.toggle('current', i === cursor);
    });
    $('prev').hidden = !features.enablePreviousButton || cursor <= 0;
    $('restart').hidden = !features.enableRestartButton || cursor < 0;
  }

  function reveal(index = nextIndex()) {
    if (busy || pack.open || robo.open || !facts[index]) return;
    busy = true;
    cursor = index;
    const fact = facts[index];
    question.textContent = fact.question;
    $('answer').textContent = fact.orbAnswer;
    ball.classList.remove('revealed');
    ball.classList.add('shaking', 'thinking');
    wakeOrb();
    ball.setAttribute('aria-busy', 'true');
    $('factTitle').textContent = messages.thinkingTitle;
    $('factBody').textContent = '';
    $('hint').textContent = messages.thinkingHint;
    update();
    timer = setTimeout(() => {
      ball.classList.remove('shaking', 'thinking');
      ball.classList.add('revealed');
      wakeOrb();
      ball.removeAttribute('aria-busy');
      $('factTitle').textContent = fact.answerTitle;
      $('factBody').textContent = fact.answerBody;
      appendAction(fact.action);
      $('hint').textContent = messages.revealedHint;
      revealed.add(index);
      busy = false;
      update();
    }, reduced.matches ? 0 : timing.answerRevealDelay);
  }

  function reset() {
    clearTimeout(timer);
    busy = false;
    cursor = -1;
    revealed.clear();
    ball.classList.remove('revealed', 'shaking', 'thinking');
    wakeOrb();
    ball.removeAttribute('aria-busy');
    question.textContent = facts[0].question;
    $('factTitle').textContent = messages.initialTitle;
    $('factBody').textContent = messages.initialBody;
    $('hint').textContent = messages.initialHint;
    update();
    ball.focus();
  }

  ball.addEventListener('click', () => {
    if (performance.now() > skipClickUntil) reveal();
  });
  next.addEventListener('click', () => reveal());
  $('prev').onclick = () => reveal(cursor - 1);
  $('restart').onclick = reset;

  // Pointer gestures and optional accelerometer input.
  if (features.enableMouseInteraction) {
    ball.addEventListener('pointerdown', event => {
      if (!event.isPrimary || event.button !== 0 || busy) return;
      drag = { id: event.pointerId, x: event.clientX, y: event.clientY,
        lastX: event.clientX, lastY: event.clientY, path: 0 };
      ball.setPointerCapture(event.pointerId);
      ball.classList.add('dragging');
    });
    ball.addEventListener('pointermove', event => {
      if (!drag || drag.id !== event.pointerId) return;
      drag.path += Math.hypot(event.clientX - drag.lastX, event.clientY - drag.lastY);
      drag.lastX = event.clientX;
      drag.lastY = event.clientY;
      const x = Math.max(-23, Math.min(23, (event.clientX - drag.x) * .32));
      const y = Math.max(-18, Math.min(18, (event.clientY - drag.y) * .32));
      if (!reduced.matches) {
        ball.style.setProperty('--dx', x + 'px');
        ball.style.setProperty('--dy', y + 'px');
        ball.style.setProperty('--rot', x * .5 + 'deg');
      }
    });
    function release(event, cancel = false) {
      if (!drag || drag.id !== event.pointerId) return;
      const shake = drag.path > timing.dragThreshold;
      drag = null;
      ball.classList.remove('dragging');
      ['--dx', '--dy', '--rot'].forEach(key => ball.style.removeProperty(key));
      if (shake || cancel) {
        skipClickUntil = performance.now() + timing.clickSuppression;
        if (!cancel) reveal();
      }
    }
    ball.addEventListener('pointerup', event => release(event));
    ball.addEventListener('pointercancel', event => release(event, true));
    ball.addEventListener('lostpointercapture', event => release(event, true));
  }

  const motion = $('motion');
  if (features.enablePhoneShake && window.isSecureContext && 'DeviceMotionEvent' in window &&
      matchMedia('(pointer:coarse)').matches) motion.hidden = false;

  function onMotion(event) {
    if (document.hidden || busy || pack.open || robo.open) return;
    const acceleration = event.acceleration;
    if (!acceleration || acceleration.x == null || acceleration.y == null || acceleration.z == null) return;
    const now = performance.now();
    if (now - motionLast < timing.shakeCooldown) return;
    const magnitude = Math.hypot(acceleration.x, acceleration.y, acceleration.z);
    motionSamples = motionSamples.filter(time => now - time < timing.motionWindow);
    if (magnitude > timing.motionSensitivity) motionSamples.push(now);
    if (motionSamples.length >= timing.motionSampleCount) {
      motionLast = now;
      motionSamples = [];
      reveal();
    }
  }

  motion.onclick = async () => {
    if (!features.enablePhoneShake) return;
    if (motionEnabled) {
      window.removeEventListener('devicemotion', onMotion);
      motionEnabled = false;
      motion.textContent = messages.enableMotion;
      $('motionStatus').textContent = messages.motionDisabledStatus;
      return;
    }
    try {
      if (typeof DeviceMotionEvent.requestPermission === 'function' &&
          await DeviceMotionEvent.requestPermission() !== 'granted') throw Error('Permission denied');
      window.addEventListener('devicemotion', onMotion);
      motionEnabled = true;
      motionSamples = [];
      motion.textContent = messages.disableMotion;
      $('motionStatus').textContent = messages.motionEnabledStatus;
    } catch {
      motion.textContent = messages.motionUnavailable;
      $('motionStatus').textContent = messages.motionUnavailableStatus;
    }
  };

  // Contract with the original Probably Stable renderer. Keep these keys stable.
  const orbBridge = window.PSOrbBridge = {
    x: 0, y: 0, impulse: 0, enabled: false, available: false, mode: 'fallback',
    settings: orbSettings,
    get reduced() { return reduced.matches; },
    state() {
      return {
        thinking: ball.classList.contains('thinking'),
        revealed: ball.classList.contains('revealed'),
        answer: $('answer').textContent,
        locked: false, onbreak: false, cracked: false
      };
    }
  };
  const orbArea = document.querySelector('.scene');
  if (features.enableMouseInteraction) {
    orbArea.addEventListener('pointermove', event => {
      if (event.pointerType !== 'mouse' || orbBridge.enabled || orbBridge.reduced) return;
      const r = orbArea.getBoundingClientRect();
      orbBridge.x = Math.max(-1, Math.min(1, 2 * (event.clientX - r.left) / r.width - 1));
      orbBridge.y = Math.max(-1, Math.min(1, 2 * (event.clientY - r.top) / r.height - 1));
      wakeOrb();
    });
    orbArea.addEventListener('pointerleave', () => {
      if (!orbBridge.enabled) { orbBridge.x = orbBridge.y = 0; wakeOrb(); }
    });
  }
  ball.addEventListener('pointerdown', wakeOrb);
  ball.addEventListener('keydown', event => {
    if (event.key === ' ' || event.key === 'Enter') wakeOrb();
  });
  new ResizeObserver(() => {
    if (orbBridge.mode === 'webgl') return;
    const r = orbArea.getBoundingClientRect();
    const size = Math.max(1, Math.min(r.width * .88, r.height * .84));
    ball.style.width = size + 'px';
    ball.style.height = size + 'px';
  }).observe(orbArea);

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && $('index').open) {
      $('index').open = false;
      $('index').querySelector('summary').focus();
    }
  });
  document.addEventListener('pointerdown', event => {
    if ($('index').open && !$('index').contains(event.target)) $('index').open = false;
  });

  question.textContent = facts[0].question;
  update();
  if (features.debug) console.info('RyanStevens.dev', { questionCount: facts.length, orb: orbSettings });
}

